CREATE TABLE users (id VARCHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, role VARCHAR(20) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL);
CREATE TABLE tickets (id VARCHAR(36) PRIMARY KEY, ticket_number VARCHAR(20) UNIQUE NOT NULL, customer_id VARCHAR(36), customer_email VARCHAR(255) NOT NULL, order_id VARCHAR(80), category VARCHAR(30) NOT NULL, subject VARCHAR(200) NOT NULL, description TEXT NOT NULL, priority VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL, assigned_agent_id VARCHAR(36), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, resolved_at TIMESTAMP, closed_at TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES users(id), FOREIGN KEY(assigned_agent_id) REFERENCES users(id));
CREATE TABLE ticket_messages (id VARCHAR(36) PRIMARY KEY, ticket_id VARCHAR(36) NOT NULL, sender_id VARCHAR(36), sender_name VARCHAR(120) NOT NULL, message TEXT NOT NULL, message_type VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL, FOREIGN KEY(ticket_id) REFERENCES tickets(id));
CREATE TABLE ticket_events (id VARCHAR(36) PRIMARY KEY, ticket_id VARCHAR(36) NOT NULL, actor_id VARCHAR(36), actor_name VARCHAR(120) NOT NULL, event_type VARCHAR(30) NOT NULL, old_value VARCHAR(120), new_value VARCHAR(120), created_at TIMESTAMP NOT NULL, FOREIGN KEY(ticket_id) REFERENCES tickets(id));

